#!/usr/bin/env bash
# ============================================================================
# FIRONOVA — Installeur automatisations email (idempotent)
# Ajoute: relance panier abandonné (watchdog) + email de bienvenue à l'inscription.
# À exécuter depuis /app :  bash install_email_automation.sh
# ============================================================================
set -euo pipefail
cd "$(dirname "$0")"
SERVER="backend/server.py"; [ -f "$SERVER" ] || SERVER="server.py"
[ -f "$SERVER" ] || { echo "server.py introuvable"; exit 1; }
cp "$SERVER" "${SERVER}.bak-autom-$(date +%Y%m%d-%H%M%S)"
echo "Backup créé."
export AUTOM_B64=''

python3 - "$SERVER" << 'PYEOF'
import sys, re, ast, base64, os
path = sys.argv[1]
src = open(path).read()

# 1) Bloc automatisations (idempotent)
BLOCK = base64.b64decode(os.environ["AUTOM_B64"]).decode()
wrapped = "\n\n# ===== FIRONOVA_EMAIL_AUTOMATION_START =====\n" + BLOCK + "\n# ===== FIRONOVA_EMAIL_AUTOMATION_END =====\n"
if "FIRONOVA_EMAIL_AUTOMATION_START" in src:
    src = re.sub(r"# ===== FIRONOVA_EMAIL_AUTOMATION_START =====.*?# ===== FIRONOVA_EMAIL_AUTOMATION_END =====\n", wrapped.strip()+"\n", src, flags=re.DOTALL)
    print("  bloc automatisations remplace")
else:
    src = src.replace("app.include_router(api)", wrapped + "\napp.include_router(api)", 1)
    print("  bloc automatisations injecte")

# 2) Email de bienvenue dans register() (idempotent)
if "welcome_new_user(" not in src.split("FIRONOVA_EMAIL_AUTOMATION_START")[0]:
    anchor = '    token = create_access_token(user_doc["id"], email, "user", token_version=0)\n    set_auth_cookie(response, token, request)'
    inject = ('    # --- AUTOMATION: email de bienvenue (n\'interrompt jamais l\'inscription) ---\n'
              '    asyncio.create_task(welcome_new_user(email, user_doc.get("name", ""), "fr"))\n'
              '    token = create_access_token(user_doc["id"], email, "user", token_version=0)\n'
              '    set_auth_cookie(response, token, request)')
    if anchor in src:
        src = src.replace(anchor, inject, 1); print("  email bienvenue greffe dans register()")
    else:
        print("  ! ancre register() introuvable")
else:
    print("  email bienvenue deja present")

# 3) Watchdog au startup (idempotent)
if "_abandoned_cart_watchdog()" not in src.split("FIRONOVA_EMAIL_AUTOMATION_START")[0]:
    a = '        asyncio.create_task(_magic_tokens_cleanup())'
    b = ('        asyncio.create_task(_magic_tokens_cleanup())\n'
         '        asyncio.create_task(_abandoned_cart_watchdog())')
    if a in src:
        src = src.replace(a, b, 1); print("  watchdog panier abandonne lance au startup")
    else:
        print("  ! ancre startup introuvable")
else:
    print("  watchdog deja lance")

ast.parse(src); open(path,"w").write(src)
print("OK - server.py a jour, AST valide.")
PYEOF
echo "Termine. Redemarre le backend."
